//! Typed commands exposed to the frontend (TypeScript types generated by tauri-specta).

use crate::state::AppState;
use momentum_core::Theme;
use serde::{Deserialize, Serialize};
use specta::Type;
use tauri::{AppHandle, State};

#[derive(Debug, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct AppInfo {
    pub version: String,
    /// `macos`, `windows`, `linux`.
    pub platform: String,
    pub arch: String,
    pub schema_version: i32,
    pub vibrancy: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct Preferences {
    pub theme: Theme,
    /// BCP 47 language tag, `None` = follow the OS.
    pub language: Option<String>,
}

#[derive(Debug, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct CategoryDto {
    pub id: String,
    pub title: String,
    pub hex_color: String,
    pub archived: bool,
    pub position: i32,
}

/// Errors are surfaced to the UI as plain strings.
type CmdResult<T> = Result<T, String>;

fn err(e: impl std::fmt::Display) -> String {
    e.to_string()
}

const PREF_THEME: &str = "appearance.theme";
const PREF_LANGUAGE: &str = "general.language";

#[tauri::command]
#[specta::specta]
pub fn get_app_info(app: AppHandle, state: State<'_, AppState>) -> CmdResult<AppInfo> {
    let store = state.store.lock().map_err(err)?;
    Ok(AppInfo {
        version: app.package_info().version.to_string(),
        platform: std::env::consts::OS.to_owned(),
        arch: std::env::consts::ARCH.to_owned(),
        schema_version: i32::try_from(store.schema_version().map_err(err)?).unwrap_or(-1),
        vibrancy: *state.vibrancy.lock().map_err(err)?,
    })
}

#[tauri::command]
#[specta::specta]
pub fn get_preferences(state: State<'_, AppState>) -> CmdResult<Preferences> {
    let store = state.store.lock().map_err(err)?;
    Ok(Preferences {
        theme: store
            .get_setting(PREF_THEME)
            .map_err(err)?
            .unwrap_or(Theme::Dark),
        language: store.get_setting(PREF_LANGUAGE).map_err(err)?.flatten(),
    })
}

#[tauri::command]
#[specta::specta]
pub fn set_preferences(state: State<'_, AppState>, prefs: Preferences) -> CmdResult<Preferences> {
    let store = state.store.lock().map_err(err)?;
    store.set_setting(PREF_THEME, &prefs.theme).map_err(err)?;
    store
        .set_setting(PREF_LANGUAGE, &prefs.language)
        .map_err(err)?;
    Ok(prefs)
}

#[tauri::command]
#[specta::specta]
pub fn list_categories(state: State<'_, AppState>) -> CmdResult<Vec<CategoryDto>> {
    let store = state.store.lock().map_err(err)?;
    Ok(store
        .list_categories()
        .map_err(err)?
        .into_iter()
        .map(|c| CategoryDto {
            archived: c.status == momentum_core::CategoryStatus::Archived,
            id: c.id,
            title: c.title,
            hex_color: c.hex_color,
            position: i32::try_from(c.position).unwrap_or(i32::MAX),
        })
        .collect())
}

/// Called once the UI has rendered. In smoke-test mode this ends the process successfully.
#[tauri::command]
#[specta::specta]
pub fn frontend_ready(app: AppHandle, state: State<'_, AppState>) {
    if state.smoke_test {
        crate::smoke::succeed(&app);
    }
}
